/// One version of QMK's keycode spec (`data/constants/keycodes`), as generated by
/// `Tools/gen-keycodes.py` into `Keycodes/Generated/`.
public struct QMKKeycodeSpec: Sendable {
    public struct Range: Sendable, Hashable {
        public let start: UInt16
        public let last: UInt16
        public let define: String

        public func contains(_ code: UInt16) -> Bool { (start...last).contains(code) }
        public var size: Int { Int(last) - Int(start) + 1 }
    }

    public struct Entry: Sendable, Hashable {
        public let code: UInt16
        /// Canonical QMK name, for example `KC_ESCAPE`.
        public let key: String
        /// QMK's human label, for example `Esc`. Missing for a few legacy names.
        public let label: String?
        /// QMK group: basic, modifiers, media, mouse, quantum, underglow, rgb_matrix, macro, kb, ...
        public let group: String
        /// Short names, for example `KC_ESC`.
        public let aliases: [String]

        /// The shortest QMK name, used in raw keycode text such as `LGUI(KC_0)`.
        public var shortName: String { ([key] + aliases).min { $0.count < $1.count } ?? key }
    }

    public let version: String
    public let ranges: [Range]
    public let keycodes: [Entry]
}
